const ALICE = "01HZZZAAAAAAAAAAAAAAAAAAAA" as UserId;
const BOB = "01HZZZBBBBBBBBBBBBBBBBBBBB" as UserId;

function actor(role: Role, overrides: Partial<Actor> = {}): Actor {
20→  return { userId: ALICE, orgId: ORG, role, ...overrides };
}

