function issueBy(authorId: UserId, assigneeId: UserId | null = null): PermissionResource {
  return {
    kind: "issue",
    orgId: ORG,
    projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
30→    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
    authorId,
