/**
 * Per-workspace member absences. One row per member; a later set replaces it.
 *
 * Reads and writes are always filtered by `orgId`. Delegation is a single hop:
 * callers that redirect work must not follow a delegate's own absence.
 */
import { and, eq } from "drizzle-orm";
import { getDb, memberAbsences } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { findMember } from "./member-repository";
import type { SetAbsenceInput } from "@/schemas/member";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

function toAbsence(row: typeof memberAbsences.$inferSelect): MemberAbsence {
  return {
    orgId: row.orgId as OrgId,
    userId: row.userId as UserId,
    delegateUserId: row.delegateUserId === null ? null : (row.delegateUserId as UserId),
    startsAt: row.startsAt as IsoTimestamp,
    endsAt: row.endsAt as IsoTimestamp,
    note: row.note,
  };
}

/** True while `now` is in `[startsAt, endsAt)`. */
export function isAway(absence: MemberAbsence, now: Date): boolean {
  const at = now.getTime();
  return at >= Date.parse(absence.startsAt) && at < Date.parse(absence.endsAt);
}

/** True once `now` has reached the exclusive end. */
export function hasEnded(absence: MemberAbsence, now: Date): boolean {
  return now.getTime() >= Date.parse(absence.endsAt);
}

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.userId, userId)),
    )
    .get();
  return row ? toAbsence(row) : null;
}

export async function upsertAbsence(input: SetAbsenceInput): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId: input.orgId,
      userId: input.userId,
      delegateUserId: input.delegateUserId,
      startsAt: input.startsAt,
      endsAt: input.endsAt,
      note: input.note,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: input.delegateUserId,
        startsAt: input.startsAt,
        endsAt: input.endsAt,
        note: input.note,
        updatedAt: stamp,
      },
    })
    .returning()
    .get();

  return toAbsence(row);
}

export async function deleteAbsence(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(orgPredicate(memberAbsences.orgId, orgId), eq(memberAbsences.userId, userId)),
    )
    .run();
}

/** Drops this user as anyone's delegate in the workspace. The absence stays. */
export async function clearDelegate(orgId: OrgId, delegateUserId: UserId): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, delegateUserId),
      ),
    )
    .run();
}

/**
 * Who should receive work addressed to `userId` right now.
 * One hop only: an away delegate is not followed. A missing or inactive
 * delegate leaves the work with `userId`.
 */
export async function assignmentTarget(
  orgId: OrgId,
  userId: UserId,
  now: Date,
): Promise<UserId> {
  const absence = await findAbsence(orgId, userId);
  if (!absence || absence.delegateUserId === null || !isAway(absence, now)) {
    return userId;
  }

  const delegate = await findMember(orgId, absence.delegateUserId);
  if (!delegate || delegate.status !== "active") return userId;
  return absence.delegateUserId;
}

/**
 * Mention recipients plus the delegate of each mentioned member who is away.
 * The original member stays in the list; callers dedupe.
 */
export async function mentionAlertRecipients(
  orgId: OrgId,
  mentionedUserIds: readonly UserId[],
  now: Date,
): Promise<UserId[]> {
  const recipients = [...mentionedUserIds];
  for (const userId of mentionedUserIds) {
    const target = await assignmentTarget(orgId, userId, now);
    if (target !== userId) recipients.push(target);
  }
  return recipients;
}

